template<size_t N>static void put(char(&d)[N],const std::string& s){snprintf(d,N,"%s",s.c_str());}
const char* sportingReputation(int r){return r<20?"Local":r<35?"Régional":r<55?"National":r<70?"Continental":r<85?"International":"Élite";}
const char* sportingPower(int p){static const char* n[]={"Limité","Standard","Fort","Total"};return n[std::clamp(p,0,3)];}
const char* sportingObjective(int o){static const char* n[]={"Maintien","Première moitié","Montée / Europe","Titre","Budget positif","Réduire les salaires","Former les jeunes","Recruter local"};return n[std::clamp(o,0,7)];}
const char* sportingStatus(int i){static const char* n[]={"Titulaire","Important","Rotation","Espoir","À vendre","À prêter","Intouchable","Fin de cycle"};return n[std::clamp(i,0,7)];}
static SportingCoach* sdFindCoach(Career& K,int club){for(auto& c:K.sporting.coaches)if(c.club==club)return &c;return nullptr;}
static void event(Career& K,int kind,const std::string& msg){SportingMeeting m;m.kind=kind;m.year=K.year;m.month=(int)(K.season.now/4.2);put(m.text,msg);K.sporting.meetings.push_back(m);if(K.sporting.meetings.size()>240)K.sporting.meetings.erase(K.sporting.meetings.begin());K.season.news.push_back("[Direction sportive] "+msg);if(K.sporting.employed&&kind!=1){K.museumState(K.userTeam);auto& h=K.clubHistories[K.userTeam];MuseumEvent e;e.year=K.year;e.time=K.season.now;e.category=MH_MANAGER;put(e.text,"Direction sportive : "+msg);h.timeline.push_back(e);}}
SportingCoach sportingCoachCandidate(int club,int level,int seed){Rng r(hashStr(g_world.teams[club].name)^seed*31337ULL);auto staff=makeStaff(SR_ADJOINT,std::clamp(level,1,5),g_world.teams[club].status,r);SportingCoach c;c.club=club;put(c.name,staff.name);c.age=staff.age;c.wage=staff.wage;c.reputation=std::clamp(level*17+r.range(-5,5),5,95);c.philosophy=r.range(0,DPH_COUNT-1);c.formation=r.range(0,NUM_FORMATIONS-1);c.style=r.range(0,2);c.youth=c.philosophy==DP_YOUNG||c.philosophy==DP_ACADEMY?85:r.range(20,70);c.discipline=r.range(30,90);c.adaptation=r.range(30,90);c.dressing=r.range(30,90);c.demand=r.range(30,90);return c;}
int sportingCompatibility(const SportingCareer& S,const SportingCoach& C){int n=55+(C.philosophy==S.profile.philosophy?25:0)-std::abs(C.youth-S.policy.youth)/3;if((S.profile.philosophy==DP_YOUNG||S.profile.philosophy==DP_ACADEMY)&&C.philosophy==DP_EXPERIENCED)n-=20;n+=(S.profile.skills[SD_COACH]+C.adaptation)/15;return std::clamp(n,0,100);}
void Career::sportingLearn(int k,int amount){if(!sportingMode()||k<0||k>=SD_SKILLS)return;auto& P=sporting.profile;P.xp[k]=(uint16_t)std::min(65000,(int)P.xp[k]+amount);while(P.xp[k]>=100&&P.skills[k]<99){P.xp[k]-=100;P.skills[k]++;}}
void Career::sportingStart(int club,int yr,const SportingProfile& P){int base=club;if(base<0){for(auto& p:g_basePyramids)if(p.country=="FRA"&&p.dom<0)for(auto& pool:p.pools)if(pool.tier>=8&&!pool.clubs.empty()){base=pool.clubs[0];break;}}if(base<0)base=g_world.firstClub;opts=Opts();opts.disableBribes=1;newClubCareer(base,yr);sporting=SportingCareer();auto& S=sporting;S.active=1;S.profile=P;S.profile.age=std::clamp(P.age,25,70);S.profile.reputation=std::clamp(P.reputation,0,99);bool empty=true;for(auto v:P.skills)empty&=v==0;if(empty){for(auto& v:S.profile.skills)v=(uint8_t)std::clamp(25+P.experience+P.reputation/3,10,85);S.profile.skills[std::clamp(P.specialty,0,SD_SKILLS-1)]=(uint8_t)std::min(95,(int)S.profile.skills[std::clamp(P.specialty,0,SD_SKILLS-1)]+15);}S.planStart=yr;SportingNetwork net;net.nation=S.profile.nation;net.knowledge=50;S.network.push_back(net);for(int i=0;i<24;i++){SportingAgent a;a.id=i;a.reputation=20+i*3;a.demand=30+i*2;put(a.name,"Agence sportive "+std::to_string(i+1));S.agents.push_back(a);}if(club>=0&&!(P.start==0&&g_world.teams[club].status==CS_PRO))sportingAttach(club);else{S.employed=0;season.controlled.clear();put(S.reason,"Début de carrière sans club : consultez les emplois.");sportingJobs();}}
void Career::sportingAttach(int club){auto& S=sporting;if(club<0||club>=(int)g_world.teams.size())return;if(S.employed)sportingLeave(0,"Nouveau poste accepté.");if(userTeam!=club)changeClub(club);S.employed=1;mgr.sacked=0;mgr.managerMode=1;mgr.fullManager=0;mgr.delegSubs=1;mgr.delegTrain=1;life.isPlayer=0;season.controlled={club};S.contractYears=3;S.trust=std::clamp(40+S.profile.reputation/5,40,65);S.coachTrust=50;S.power=std::clamp((S.profile.reputation+S.profile.skills[SD_DIPLOMACY]/2)/30,0,3);if(g_world.teams[club].status==CS_AMATEUR)S.power=std::min(S.power,1);S.wage=staffWage(std::clamp(1+S.profile.reputation/20,1,5),g_world.teams[club].status);S.wageStart=wageBill(club);S.transferBudget=std::max<int64_t>(0,mgr.budget)*std::min(60,20+S.power*12)/100;S.staffBudget=std::max<int64_t>(10,mgr.incomeBase/10);S.scoutBudget=std::max<int64_t>(0,mgr.budget)/50;S.youthBudget=std::max<int64_t>(0,mgr.budget)*S.policy.youthBudgetPct/100;S.salesGoal=std::max<int64_t>(0,mgr.incomeBase)/10;S.seasonYear=year;S.relationMonth=-1;S.relationYear=year;S.departure=0;S.objective=mgr.objective==0?3:mgr.objective==1||mgr.objective==2?2:mgr.objective==3?1:0;S.reason[0]=0;S.players.clear();S.partners.clear();director=DirectorState();StaffMember human;put(human.name,std::string(S.profile.first)+" "+S.profile.last);human.role=SR_DIRECTOR;human.level=3;human.age=S.profile.age;human.wage=S.wage;mgr.staff.erase(std::remove_if(mgr.staff.begin(),mgr.staff.end(),[](auto s){return s.role==SR_DIRECTOR;}),mgr.staff.end());mgr.staff.push_back(human);directorSync();director.limits.budgetPct=std::min(60,20+S.power*12);director.limits.maxFee=(int)std::min<int64_t>(100000000,S.transferBudget);for(int d:{DD_OFFERS,DD_FEES,DD_CONTRACTS,DD_AGENTS})director.mode[d]=DM_NEGOTIATE;director.mode[DD_LOAN_IN]=DM_NEGOTIATE;if(!sdFindCoach(*this,club)){auto c=sportingCoachCandidate(club,g_world.teams[club].status==CS_PRO?3:1,year);c.lastYear=year;S.coaches.push_back(c);}SportingHistory h;h.club=club;h.from=year;S.history.push_back(h);sportingPrepare(club);event(*this,0,"Prise de poste : "+g_world.teams[club].name+". Pouvoir "+sportingPower(S.power)+" ; objectif "+sportingObjective(S.objective)+".");}
void Career::sportingPrepare(int club){if(!sportingMode()||club<0||club>=(int)g_world.teams.size()||g_world.teams[club].kind!=TK_CLUB||g_world.teams[club].freeAgents)return;auto* C=sdFindCoach(*this,club);if(!C&&club!=userTeam&&(teamLevel(club)>3||g_world.teams[club].nation!=g_world.teams[userTeam].nation))return;if(!C){auto candidate=sportingCoachCandidate(club,std::clamp((int)g_world.teams[club].rating/22,1,5),year);candidate.lastYear=year;sporting.coaches.push_back(candidate);C=&sporting.coaches.back();}Team& T=g_world.teams[club];if(C->lastYear<year){C->years-=year-C->lastYear;C->lastYear=year;if(C->years<=0){if(club==userTeam&&sporting.employed)event(*this,2,"Contrat du coach arrivé à échéance : coach intérimaire nommé.");auto replacement=sportingCoachCandidate(club,std::clamp((int)T.rating/22,1,5),year+17);replacement.lastYear=year;*C=replacement;}}
 T.formation=std::clamp(C->formation,0,NUM_FORMATIONS-1);T.xi.clear();T.passStyle=C->style==0?0:C->style==2?2:1;T.tempo=C->style==2?2:1;T.pressing=C->discipline>65?2:1;T.mentality=C->style==2?3:2;T.tactical.customized=1;T.tactical.model=C->style==0?0:1;for(int slot=0;slot<11;slot++){int pos=slotPosition(T.formation,slot);T.tactical.slot[slot]=defaultSlotTactic(pos,T.tactical.model,slot);}if(club==userTeam&&sporting.employed){managerName=C->name;supportersOnManagerChange(club,managerName);mgr.trainFocus=C->style==0?2:C->style==2?4:0;mgr.trainInt=C->discipline>70?2:1;mgr.delegTrain=0;auto lu=g_world.pickLineup(club,T.formation,RULESET_CAREER);if(C->youth>70&&sporting.policy.youth>50){std::set<int> used;for(int i:lu)if(i>=0)used.insert(i);for(int slot=1;slot<11&&slot<(int)lu.size();slot++){int best=lu[slot];if(best<0)continue;int pos=slotPosition(T.formation,slot);for(int i=0;i<(int)T.squad.size();i++)if(!used.count(i)&&T.squad[i].age<=21&&T.squad[i].injured<=0&&T.squad[i].suspended<=0&&positionFamiliarity(T.squad[i],pos)>=65&&T.squad[i].overall()>=T.squad[best].overall()-4){used.erase(best);used.insert(i);lu[slot]=i;break;}}}for(int slot=0;slot<11&&slot<(int)lu.size();slot++){int i=lu[slot];if(i>=0)T.xi.push_back(T.squad[i].id);}}}
void Career::sportingJobs(){if(!sportingMode())return;auto& S=sporting;int stamp=year*12+(int)(season.now/4.2);if(S.applicationMonth==stamp&&!S.jobs.empty())return;S.applicationMonth=stamp;S.jobs.clear();std::vector<std::pair<int,int>> v;for(auto& P:pyramids)if(P.dom<0)for(auto& pool:P.pools)for(int t:pool.clubs){auto& T=g_world.teams[t];if(t==userTeam&&S.employed||T.parent>=0||T.youth||T.kind!=TK_CLUB||T.freeAgents)continue;if(teamReputation(t)>S.profile.reputation+35)continue;int fit=std::abs(teamReputation(t)-S.profile.reputation)+(T.nation==S.profile.nation?-15:10);if(S.profile.start==0&&S.profile.reputation<35&&T.status==CS_PRO)continue;v.push_back({fit,t});}std::sort(v.begin(),v.end());std::set<int> unique;for(auto item:v)if(unique.insert(item.second).second){SportingJob j;j.club=item.second;j.power=std::clamp(S.profile.reputation/25,0,3);j.wage=staffWage(std::clamp(1+S.profile.reputation/20,1,5),g_world.teams[j.club].status);j.interested=std::clamp(70+S.profile.reputation-teamReputation(j.club)+S.profile.skills[SD_DIPLOMACY]/5,20,95);S.jobs.push_back(j);if(S.jobs.size()==18)break;}}
bool Career::sportingApply(int club,bool negotiate,std::string& msg){sportingJobs();auto& S=sporting;auto it=std::find_if(S.jobs.begin(),S.jobs.end(),[&](auto j){return j.club==club&&!j.refused;});if(it==S.jobs.end()){msg="Poste indisponible pour votre réputation actuelle.";return false;}if(negotiate){if(it->negotiated){msg="Cette offre a déjà été négociée.";return false;}it->negotiated=1;if(S.profile.skills[SD_DIPLOMACY]+it->interested>=105){it->wage=it->wage*110/100;it->power=std::min(3,it->power+1);msg="Proposition améliorée : salaire et pouvoir négociés.";return true;}it->refused=1;msg="Le club retire sa proposition.";return false;}if(it->interested<45){it->refused=1;msg="Votre candidature n’est pas retenue.";return false;}int wage=it->wage,power=it->power;sportingAttach(club);S.wage=wage;S.power=power;for(auto& s:mgr.staff)if(s.role==SR_DIRECTOR)s.wage=wage;sportingLearn(SD_DIPLOMACY,30);msg="Contrat de trois saisons signé comme directeur sportif.";return true;}
void Career::sportingLeave(int when,const std::string& why){if(!sportingMode())return;auto& S=sporting;if(when>0){S.departure=when;event(*this,5,when==1?"Départ prévu à la fin de la saison.":"Départ prévu à la fin du contrat.");return;}if(S.employed){for(auto it=S.history.rbegin();it!=S.history.rend();++it)if(it->club==userTeam&&!it->to){it->to=year;break;}mgr.staff.erase(std::remove_if(mgr.staff.begin(),mgr.staff.end(),[](auto s){return s.role==SR_DIRECTOR;}),mgr.staff.end());}S.employed=0;S.departure=0;mgr.sacked=0;season.controlled.clear();put(S.reason,why);for(auto& n:director.negotiations)if(n.phase<DN_DONE)n.phase=DN_CANCELLED;sportingJobs();}
bool Career::sportingRenew(std::string& msg){auto& S=sporting;if(!S.employed||S.trust<35||S.contractYears>1){msg="Prolongation disponible dans la dernière saison, avec la confiance du président.";return false;}S.contractYears=3;S.wage=S.wage*(100+S.profile.skills[SD_DIPLOMACY]/20)/100;for(auto& s:mgr.staff)if(s.role==SR_DIRECTOR)s.wage=S.wage;msg="Votre contrat est renouvelé pour trois saisons.";sportingLearn(SD_DIPLOMACY,35);return true;}
bool Career::sportingBoard(int pid,int fee,int wage,std::string& msg){auto& S=sporting;if(!S.employed||fee<0||wage<0||fee>mgr.budget||fee>S.transferBudget||S.trust<30||hasDncg()&&mgr.dncg&&fee){msg="Le président refuse : finances, confiance ou DNCG incompatibles.";event(*this,3,msg);return false;}S.approvedPid=pid;S.approvedFee=fee;S.approvedWage=wage;msg="Le président valide cette proposition précise ; les autres plafonds restent actifs.";sportingLearn(SD_DIPLOMACY,10);event(*this,3,msg);return true;}
bool Career::sportingSpend(int pid,int fee,int wage,std::string& msg,int oldWage)const{if(!sportingMode())return true;auto& S=sporting;if(!S.employed){msg="Vous n'avez pas de mandat dans ce club.";return false;}if(fee>S.transferBudget||!directorCanSpend(fee,wage,msg,oldWage))return false;auto* C=sdFindCoach(const_cast<Career&>(*this),userTeam);int64_t staffCost=0;for(auto& staff:mgr.staff)staffCost+=staff.wage;if(C&&wageBill(userTeam)+staffCost+C->wage-oldWage+wage>std::min(director.limits.wageCap,director.limits.boardWages)){msg="Plafond salarial avec le coach dépassé.";return false;}bool large=fee>S.transferBudget*(20+S.power*20)/100||wage>director.limits.maxWage*(40+S.power*20)/100;if(S.power<3&&large&&!(S.approvedPid==pid&&fee<=S.approvedFee&&wage<=S.approvedWage)){msg="Validation du président requise pour cette dépense.";return false;}return true;}
bool Career::sportingHireCoach(const SportingCoach& candidate,bool dismiss,std::string& msg){auto& S=sporting;if(!S.employed){msg="Aucun club.";return false;}auto* old=sdFindCoach(*this,userTeam);if(!dismiss&&old){old->years=3;msg="Entraîneur renouvelé pour trois saisons.";return true;}int indemnity=old?old->wage*std::max(0,old->years)/4:0;if(S.power<2&&S.approvedCoach!=1){msg="Le président doit approuver le changement de coach.";return false;}if(candidate.reputation>S.profile.reputation+35||candidate.wage>S.staffBudget||indemnity>mgr.budget){msg="Coach inaccessible ou budget staff / indemnité insuffisant.";return false;}mgr.budget-=indemnity;SportingCoach c=candidate;c.club=userTeam;c.lastYear=year;c.years=3;if(old)*old=c;else S.coaches.push_back(c);S.approvedCoach=0;S.coachTrust=sportingCompatibility(S,c);for(auto& h:S.history)if(h.club==userTeam&&!h.to)h.coaches++;sportingPrepare(userTeam);sportingLearn(SD_COACH,40);event(*this,2,"Entraîneur engagé : "+std::string(c.name)+". Indemnité : "+money(indemnity)+" ; compatibilité "+std::to_string(S.coachTrust)+" %.");msg="Nouvel entraîneur en place.";return true;}
bool Career::sportingProject(std::string& msg){auto& S=sporting;if(!S.employed||S.plan[0]>S.objective+1||S.plan[2]>S.plan[0]+2){msg="Le président refuse un projet trop ambitieux.";S.planApproved=0;return false;}if(!S.planApproved){S.planStart=year;S.trust=std::min(100,S.trust+2);sportingLearn(SD_VISION,30);}S.planApproved=1;msg="Projet à 1, 3 et 5 saisons approuvé.";event(*this,0,msg);return true;}
bool Career::sportingMeeting(int choice,std::string& msg){auto& S=sporting;if(!S.employed){msg="Aucun président à rencontrer.";return false;}int stamp=year*12+(int)(season.now/4.2);for(auto& m:S.meetings)if(m.kind==8&&m.year*12+m.month==stamp){msg="Une réunion de décision a déjà eu lieu ce mois-ci.";return false;}bool yes=S.trust+S.profile.skills[SD_DIPLOMACY]>=105&&mgr.budget>=0;if(choice==0){if(yes)S.transferBudget=std::min<int64_t>(mgr.budget*80/100,S.transferBudget+mgr.budget/10);msg=yes?"Réallocation acceptée ; le budget global reste inchangé.":"Réallocation refusée : confiance ou trésorerie insuffisante.";director.limits.budgetPct=(int)std::clamp<int64_t>(S.transferBudget*100/std::max<int64_t>(1,director.limits.budgetBase),0,80);}else if(choice==1){S.approvedCoach=yes;msg=yes?"Le président approuve un changement d'entraîneur.":"Le président refuse le licenciement du coach.";}else{S.trust=std::min(100,S.trust+(yes?3:0));msg=yes?"Le président soutient votre projet jeunes.":"Le président attend des résultats avant de donner plus de moyens.";}event(*this,8,msg);sportingLearn(SD_DIPLOMACY,10);return yes;}
void Career::sportingTransfer(const Player& P,int from,int to,int fee){if(!sportingMode()||!sporting.employed)return;auto& S=sporting;for(auto l:loans)if(l.pid==P.id)return;if(to==userTeam){bool loan=false;for(auto l:loans)if(l.pid==P.id)loan=true;if(loan)return;SportingTrade t;t.pid=P.id;t.club=userTeam;t.boughtYear=year;t.fee=fee;t.salary=playerWage(P);put(t.name,P.name);S.trades.push_back(t);S.transferBudget=std::max<int64_t>(0,S.transferBudget-fee);for(auto& h:S.history)if(h.club==userTeam&&!h.to){h.spent+=fee;h.young+=P.age<=21;}sportingLearn(SD_RECRUIT,25);sportingLearn(SD_NEGOTIATE,20);S.profile.reputation=std::min(99,S.profile.reputation+1);if(S.requestPosition>=0&&positionFamiliarity(P,S.requestPosition)>=65){S.requestState=4;S.coachTrust=std::min(100,S.coachTrust+5);}int agent=P.id%24;for(auto& a:S.agents)if(a.id==agent)a.relation=std::min(100,a.relation+3);S.approvedPid=0;S.approvedFee=S.approvedWage=0;}else if(from==userTeam){for(auto& t:S.trades)if(t.pid==P.id&&t.club==userTeam&&!t.soldYear){t.soldYear=year;t.sale=fee;break;}for(auto& h:S.history)if(h.club==userTeam&&!h.to)h.sales+=fee;S.transferBudget+=fee*60/100;sportingLearn(SD_SELL,30);if(P.apps>10)S.coachTrust=std::max(0,S.coachTrust-4);}}
void Career::sportingMatch(int ci,int mi){if(!sportingMode()||!sporting.employed)return;auto& S=sporting;if(ci<0||ci>=(int)season.comps.size()||mi<0||mi>=(int)season.comps[ci].matches.size())return;uint64_t key=((uint64_t)(unsigned)year<<40)|((uint64_t)(unsigned)ci<<20)|(unsigned)mi;if(std::find(S.matchKeys.begin(),S.matchKeys.end(),key)!=S.matchKeys.end())return;S.matchKeys.push_back(key);const auto& M=season.comps[ci].matches[mi];if(M.home!=userTeam&&M.away!=userTeam)return;int gf=M.home==userTeam?M.hg:M.ag,ga=M.home==userTeam?M.ag:M.hg;S.trust=std::clamp(S.trust+(gf>ga?1:gf<ga?-1:0),0,100);sportingPrepare(userTeam);auto* coachPtr=sdFindCoach(*this,userTeam);int comp=coachPtr?sportingCompatibility(S,*coachPtr):50;S.coachTrust=std::clamp(S.coachTrust+(comp>70?1:comp<35?-1:0),0,100);for(auto& t:S.trades)if(t.club==userTeam&&!t.soldYear){int i,at=g_world.findPlayer(t.pid,&i);if(at==userTeam&&g_world.teams[at].squad[i].apps>=5){sportingLearn(SD_ANALYSIS,2);}}if(M.decisive||season.comps[ci].kind==3)event(*this,1,"Rapport du coach : "+std::to_string(gf)+" - "+std::to_string(ga)+". Confiance président "+std::to_string(S.trust)+" %.");}
void Career::sportingTick(){if(!sportingMode())return;auto& S=sporting;if(!S.employed){sportingJobs();return;}sportingPrepare(userTeam);directorSync();int month=(int)(season.now/4.2);if(S.relationYear==year&&S.relationMonth==month)return;if(S.relationYear!=year){S.matchKeys.clear();S.transferBudget=std::max<int64_t>(0,mgr.budget)*std::min(60,20+S.power*12)/100;S.scoutBudget=std::max<int64_t>(0,mgr.budget)/50;S.youthBudget=std::max<int64_t>(0,mgr.budget)*S.policy.youthBudgetPct/100;S.wageStart=wageBill(userTeam);S.approvedPid=S.approvedFee=S.approvedWage=0;}S.relationYear=year;S.relationMonth=month;auto* C=sdFindCoach(*this,userTeam);if(C)mgr.budget-=C->wage/11;S.trust=std::clamp(S.trust+(mgr.budget<0?-5:1),0,100);int compat=C?sportingCompatibility(S,*C):50;S.coachTrust=std::clamp(S.coachTrust+(compat<40?-3:compat>70?2:0),0,100);if(S.trust>75)S.power=std::min(3,S.power+1);else if(S.trust<30)S.power=std::max(0,S.power-1);if(month==0||month==5||S.trust<25)event(*this,0,"Réunion président : objectif "+std::string(sportingObjective(S.objective))+", pouvoir "+sportingPower(S.power)+" ; budget sportif "+money(S.transferBudget)+".");if(mgr.budget<0||wageBill(userTeam)>director.limits.wageCap)event(*this,3,"Alerte financière : budget négatif ou masse salariale excessive. Recrutement restreint.");if(month!=S.requestMonth||year!=S.requestYear){directorAnalyse(false);if(!director.needs.empty()&&director.needs[0].priority>40){S.requestPosition=director.needs[0].position;S.requestState=0;S.requestMonth=month;S.requestYear=year;event(*this,2,"Le coach demande un "+std::string(detailedPositionName(S.requestPosition))+". Accepter, refuser, reporter ou proposer une alternative.");}}if(S.trust<=5||S.coachTrust<=5&&S.trust<25){sportingLeave(0,"Licenciement : confiance du président perdue après les résultats / finances / conflits.");}}
void Career::sportingSeasonEnd(){if(!sportingMode())return;auto& S=sporting;if(S.seasonYear==year+1)return;S.seasonYear=year+1;S.profile.age++;S.profile.experience++;if(!S.employed)return;int position=99,clubs=1,p,q,g;bool promoted=false;if(tierOfTeam(userTeam,&p,&q,&g)>=0){auto& P=pyramids[p];auto& pool=P.pools[q];auto tb=season.comps[pool.comps[g]].table(0,0);clubs=(int)tb.size();for(int i=0;i<clubs;i++)if(tb[i].team==userTeam)position=i+1;promoted=pool.tier>0&&position<=1;}int young=0;for(auto& P:g_world.teams[userTeam].squad)young+=P.age<=21&&P.apps>=5;bool good=S.objective==0?position<=std::max(1,clubs-2):S.objective==1?position<=std::max(1,clubs/2):S.objective==2?position<=3:S.objective==3?position==1:S.objective==4?mgr.budget>=0:S.objective==5?wageBill(userTeam)<=S.wageStart:S.objective==6?young>=2:S.policy.local>=60;S.trust=std::clamp(S.trust+(good?8:-12)+(mgr.budget<0?-10:0),0,100);S.profile.reputation=std::clamp(S.profile.reputation+(good?3:-2),0,99);int trophies=0;for(auto& C:season.comps)if(C.winner==userTeam)trophies++;for(auto& h:S.history)if(h.club==userTeam&&!h.to){h.seasons++;h.trophies+=trophies;h.young+=young;}for(auto& t:S.trades)if(t.club==userTeam&&!t.soldYear)t.wageTotal+=t.salary;for(auto& network:S.network)network.knowledge=std::min(99,network.knowledge+2);sportingLearn(SD_VISION,good?50:15);sportingLearn(SD_YOUTH,young*10);event(*this,4,std::string(good?"Objectif atteint. ":"Objectif manqué. ")+"Place "+std::to_string(position)+" ; confiance "+std::to_string(S.trust)+" ; bilan des finances et des jeunes enregistré.");if(S.planApproved){int yearsDone=year-S.planStart+1;int milestone=yearsDone==1?0:yearsDone==3?1:yearsDone==5?2:-1;if(milestone>=0){int goal=S.plan[milestone];bool reached=goal==0?position<=std::max(1,clubs-2):goal==1?position<=std::max(1,clubs/2):goal==2?position<=3:position==1;S.trust=std::clamp(S.trust+(reached?3:-4),0,100);event(*this,4,std::string("Bilan du projet à ")+std::to_string(yearsDone)+" saisons : "+(reached?"objectif atteint.":"objectif manqué."));}}S.contractYears--;if(S.departure==1||S.departure==2&&S.contractYears<=0)sportingLeave(0,"Départ programmé.");else if(S.contractYears<=0)sportingLeave(0,"Votre contrat est terminé. Recherche d'un nouveau mandat.");else if(S.trust<=15)sportingLeave(0,"Licenciement à l'issue du bilan sportif et financier.");}
template<class T>static void vec(Writer& w,std::vector<T>& v){w.vpod(v);}template<class T>static void vec(Reader& r,std::vector<T>& v){unsigned n;r.pod(n);if(!r.ok||n>200000){r.ok=false;return;}long pos=ftell(r.f);fseek(r.f,0,SEEK_END);long end=ftell(r.f);fseek(r.f,pos,SEEK_SET);if(pos<0||end<pos||(uint64_t)n*sizeof(T)>(uint64_t)(end-pos)){r.ok=false;return;}v.resize(n);if(n&&fread(v.data(),sizeof(T),n,r.f)!=n)r.ok=false;}
template<class IO>static void data(IO& io,SportingCareer& s){io.pod(s.active);io.pod(s.employed);io.pod(s.profile);io.pod(s.policy);io.pod(s.scouting);io.pod(s.contractYears);io.pod(s.wage);io.pod(s.trust);io.pod(s.coachTrust);io.pod(s.power);io.pod(s.objective);io.pod(s.relationMonth);io.pod(s.relationYear);io.pod(s.seasonYear);io.pod(s.departure);io.pod(s.applicationMonth);io.pod(s.requestPosition);io.pod(s.requestState);io.pod(s.requestYear);io.pod(s.requestMonth);io.pod(s.approvedPid);io.pod(s.approvedFee);io.pod(s.approvedWage);io.pod(s.approvedCoach);io.pod(s.plan);io.pod(s.planStart);io.pod(s.planApproved);io.pod(s.transferBudget);io.pod(s.staffBudget);io.pod(s.scoutBudget);io.pod(s.youthBudget);io.pod(s.wageStart);io.pod(s.salesGoal);io.pod(s.reason);vec(io,s.coaches);vec(io,s.players);vec(io,s.network);vec(io,s.agents);vec(io,s.history);vec(io,s.trades);vec(io,s.meetings);vec(io,s.jobs);vec(io,s.partners);vec(io,s.matchKeys);}
void sportingSave(Writer& w,const Career& K){data(w,const_cast<SportingCareer&>(K.sporting));}
void sportingLoad(Reader& r,Career& K){K.sporting=SportingCareer();auto& S=K.sporting;data(r,S);S.profile.first[31]=S.profile.last[31]=S.reason[219]=0;if(S.active>1||S.employed>1||S.power<0||S.power>3||S.profile.age<20||S.profile.age>120||S.profile.nation<0||S.profile.nation>=NUM_NATIONS||S.profile.reputation<0||S.profile.reputation>99||S.profile.philosophy<0||S.profile.philosophy>=DPH_COUNT||S.trust<0||S.trust>100||S.coachTrust<0||S.coachTrust>100||S.objective<0||S.objective>7)r.ok=false;for(auto skill:S.profile.skills)if(skill>100)r.ok=false;std::set<int> clubs;for(auto& c:S.coaches){c.name[47]=0;if(c.club<0||c.club>=(int)g_world.teams.size()||!clubs.insert(c.club).second||c.formation<0||c.formation>=NUM_FORMATIONS||c.wage<0)r.ok=false;}if(S.policy.averageAge<18||S.policy.averageAge>32||S.policy.youth<0||S.policy.youth>100||S.policy.local<0||S.policy.local>100||S.policy.over30<0||S.policy.over30>15||S.scouting.nation<-1||S.scouting.nation>=NUM_NATIONS||S.scouting.position<-1||S.scouting.position>=DP_COUNT||S.scouting.minAge<13||S.scouting.maxAge>50||S.scouting.maxAge<S.scouting.minAge)r.ok=false;for(auto& n:S.network)if(n.nation<0||n.nation>=NUM_NATIONS||n.knowledge<0||n.knowledge>100)r.ok=false;for(auto& h:S.history)if(h.club<0||h.club>=(int)g_world.teams.size())r.ok=false;for(auto& j:S.jobs)if(j.club<0||j.club>=(int)g_world.teams.size())r.ok=false;for(auto& p:S.partners)if(p.club<0||p.club>=(int)g_world.teams.size())r.ok=false;for(auto& m:S.meetings)m.text[219]=0;for(auto& a:S.agents)a.name[47]=0;for(auto& t:S.trades)t.name[47]=0;}
